  console.log(chalk.green('✨ Project created successfully!'));
  console.log();
  console.log('Next steps:');
  console.log(chalk.cyan(`  cd ${name}`));
  console.log(chalk.cyan(`  ${config.packageManager} run dev`));
  console.log();
}
